def extract_and_map_abbreviation(input_string, abbreviation_map, pattern):
    # Find all matches in the input string
    matches = pattern.findall(input_string)

    ret = []
    for match in matches:
        full_name = abbreviation_map.get(match, match)
        if isinstance(full_name, list):
            ret.extend(full_name)
        else:
            ret.append(full_name)

    ret = list(set(ret))

    return ','.join(ret) if ret else None


